powerpagecomponent.content:
{
  "source": "{% comment %}
  Outcome Testing page shell.
  Every portal page extends this and fills the "content" block.
  Usage: extends 'OT Layout', then a block named content.

  Header, navigation and footer come from the site's header/footer templates;
  outcome-testing.css restyles those to Ascot Lloyd brand values.
{% endcomment %}

{% comment %}
  Roundo is the brand's single primary font (brand/ typography sheet),
  served from Fontshare, the source the sheet itself names. Weights are
  Light 300, Regular 400, Medium 500, SemiBold 600.

  The stylesheet carries a version querystring so a browser holding the
  previous file picks up changes without a hard refresh. Bump it whenever
  outcome-testing.css changes materially.
{% endcomment %}
<link rel="preconnect" href="https://api.fontshare.com" crossorigin>
<link rel="stylesheet" href="https://api.fontshare.com/v2/css?f[]=roundo@300,400,500,600&display=swap">
<link rel="stylesheet" href="/outcome-testing.css?v=10">

<main class="ot-page" id="ot-main">
  <div class="ot-page__inner">

    {% unless page.url == '/' %}
      <nav class="ot-breadcrumb" aria-label="Breadcrumb">
        <a href="/">Home</a>
        <span aria-hidden="true">/</span>
        <span aria-current="page">{{ page.title | escape }}</span>
      </nav>
    {% endunless %}

    <header class="ot-page__header">
      <h1 class="ot-page__title">{{ page.title | escape }}</h1>
      {% if page.summary and page.summary != empty %}
        <p class="ot-page__lede">{{ page.summary }}</p>
      {% endif %}
    </header>

    {% unless user %}
      <div class="ot-notice" role="status">
        You are not signed in.
        <a href="{{ website.sign_in_url_substitution }}">Sign in</a> to see your work.
      </div>
    {% endunless %}

    {% block content %}{% endblock %}

  </div>
</main>
"
}
